  "anomalies": [
    {
      "category": "footprint_mismatch",
      "components": ["C3"],
      "pins": ["C3.1", "C3.2"],
      "nets": ["unconnected-(C3-Pad1)", "GND"],
      "observed": "C3 is a 0.1uF capacitor assigned an inductor footprint; pin 1 is unconnected and pin 2 is on GND.",
      "expected": "A capacitor intended for the board should have a capacitor footprint and, if used for bypassing, connect between the relevant supply rail and GND. Otherwise it should not be included as a fitted component.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"C3\") (value \"0.1uF\") (footprint \"Inductor_SMD:L_0805_2012Metric_Pad1.05x1.20mm_HandSolder\")"
        },
        {
          "source": "netlist",
          "quote": "(net (code \"59\") (name \"unconnected-(C3-Pad1)\") (node (ref \"C3\") (pin \"1\")))"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"C3\") (pin \"2\") (pintype \"passive\"))"
        },
        {
          "source": "spice",
          "quote": "C3 unconnected-_C3-Pad1_ 0 0.1u"
        }
      ],
      "impact": "C3 provides no useful shunt capacitance because one terminal floats, and its assigned inductor footprint is unsuitable for the capacitor. If assembled as specified, this can cause a footprint or placement problem; if it was intended as bypassing, that bypass is absent.",
      "confidence": 0.91
    }
  ],
  "summary": "C3 is an unconnected 0.1uF capacitor with an inductor footprint, so it cannot serve as a functional bypass capacitor and may also be unassemblable as intended."
}

